import * as THREE from 'three';
export function buildPolicyAmenities(art,scene,plan,T){const {box,shape,line,mat}=art,records=[],picks=[],materials=new Map();
 const wall=c=>{if(!materials.has(c))materials.set(c,T.material(c,T.tile));return materials.get(c);};
 function hall(g,x,z,w,d,h,color='#d7c5a4',roof='flat'){box(wall(color),x,h/2,z,w,h,d,g);for(const a of [0,Math.PI]){const f=new THREE.Group();f.position.set(x,0,z+(a?-.5:.5)*d);f.rotation.y=a;g.add(f);for(let k=0;k<Math.max(1,Math.floor(w/3));k++)T.windowBay(-w/2+(k+.5)*w/Math.max(1,Math.floor(w/3)),h*.56,.08,1.35,Math.min(1.8,h*.55),f,false);}
  if(roof==='gable')shape('v041-gable',T.terracotta,x,h+.9,z,w+.6,1.8,d+.6,g);else{box('#e0d7c0',x,h+.15,z,w+.3,.3,d+.3,g);T.planter(x,h+.35,z+d*.2,w*.55,.7,g);}}
 function canopy(g,x,z,w,d,color='#6e9495'){box(color,x,3,z,w,.2,d,g);for(const xx of [-w/2+.3,w/2-.3])for(const zz of [-d/2+.3,d/2-.3])box('#9eaa96',x+xx,1.5,z+zz,.14,3,.14,g);}
 function bench(g,x,z,w=2.6){box('#a68c67',x,.55,z,w,.16,.7,g);box('#a68c67',x,.93,z-.3,w,.7,.12,g);for(const dx of [-w*.35,w*.35])box('#6f8072',x+dx,.3,z,.12,.5,.55,g);}
 function bus(g,x,z,red=false){box(red?'#b94d3c':'#e6dfc8',x,.9,z,2,1.65,4.8,g);box('#4e8191',x,1.15,z+2.43,1.75,.7,.08,g);for(const dx of [-1,1])for(const dz of [-1.4,1.4]){const wheel=shape('cyl','#3d4948',x+dx,.38,z+dz,.34,.16,.34,g);wheel.rotation.z=Math.PI/2;}if(red){box('#e1dbca',x,1.82,z,.25,.12,4,g);for(const dz of [-1.5,1.5])box('#577792',x,1.9,z+dz,1.4,.13,.3,g);}}
 function court(g,W,D){box('#80a081',0,.18,D*.08,W*.75,.08,D*.66,g);for(const x of [-W*.36,W*.36])line('#ece6cf',[x,.24,-D*.25],[x,.24,D*.4],.035,g);for(const z of [-D*.25,D*.08,D*.4])line('#ece6cf',[-W*.36,.24,z],[W*.36,.24,z],.035,g);for(const x of [-W*.3,W*.3]){line('#8c9d92',[x,.2,D*.08],[x,2.8,D*.08],.06,g);box('#e5dfc8',x,2.65,D*.08,1.2,.8,.1,g);}for(let k=0;k<3;k++)box('#d4cfbb',0,.25+k*.3,-D*.38-k*.4,W*.7,.3,.7,g);}
 for(const p of plan.parcels.filter(p=>p.kind==='amenity')){const g=new THREE.Group();g.name='policy-amenity-'+p.id;scene.add(g);const W=p.usableW*.94,D=p.usableD*.92,k=p.sceneKind;
  box(T.pavement,0,.08,0,W,.12,D,g);
  if(k==='transport'){box('#5a696a',0,.17,D*.14,W*.86,.10,D*.62,g);hall(g,-W*.24,-D*.28,W*.36,D*.25,3.6,'#b1c4bd');canopy(g,W*.16,-D*.20,W*.45,D*.25);for(const x of [-W*.23,W*.23])bus(g,x,D*.19);for(let j=0;j<4;j++)box('#ece1b9',W*.38,.24,-D*.1+j*D*.12,.06,.025,D*.06,g);}
  else if(['childcare','family'].includes(k)){hall(g,-W*.22,-D*.24,W*.45,D*.38,4.2,'#d8b18e','gable');box('#d3bd8b',W*.14,.18,D*.18,W*.46,.12,D*.50,g);canopy(g,W*.12,D*.11,W*.4,D*.33,'#a2b77c');for(const x of [W*.03,W*.2])for(const z of [D*.05,D*.2])box('#af8c5e',x,1.1,z,.13,2.1,.13,g);box('#d9ae68',W*.11,1.5,D*.12,W*.2,.15,D*.25,g);line('#daac55',[W*.2,1.5,D*.2],[W*.36,.25,D*.38],.17,g);}
  else if(['education','sports'].includes(k)){court(g,W,D);if(k==='education')hall(g,-W*.28,-D*.27,W*.35,D*.25,3.8,'#c8ad87','gable');}
  else if(['senior','welfare'].includes(k)){hall(g,-W*.18,-D*.20,W*.54,D*.42,4.5,'#cabb9c','gable');canopy(g,W*.15,D*.20,W*.45,D*.38);for(const x of [-W*.22,W*.22])bench(g,x,D*.28);const r=box('#cec8b5',0,.25,D*.13,2,.25,D*.6,g);r.rotation.x=-.05;}
  else if(['health','medical'].includes(k)){hall(g,-W*.16,-D*.16,W*.6,D*.53,5,'#d9ded2');box('#ba4d47',-W*.16,3.6,D*.11,.4,1.8,.15,g);box('#ba4d47',-W*.16,3.6,D*.11,1.8,.4,.15,g);canopy(g,W*.2,D*.26,W*.38,D*.24,'#80a29a');bench(g,-W*.15,D*.32);}
  else if(['environment','flood'].includes(k)){hall(g,-W*.27,-D*.23,W*.32,D*.35,3.4,'#a7b99c');for(const x of [W*.05,W*.30]){shape('v041-cyl','#a7b8ad',x,1.7,-D*.1,W*.19,3.3,W*.19,g);shape('v041-cyl','#6e9ea7',x,3.38,-D*.1,W*.18,.05,W*.18,g);}box('#8ab2b0',0,.24,D*.26,W*.7,.10,D*.3,g);for(const x of [-W*.3,W*.3])line('#b9c5b4',[x,.4,D*.13],[x,.4,D*.4],.045,g);}
  else if(k==='rescue'){hall(g,-W*.1,-D*.2,W*.75,D*.5,5,'#d3bd9c');for(const x of [-W*.2,W*.15])box('#b45a47',x,1.5,D*.06,W*.25,2.8,.12,g);bus(g,W*.18,D*.28,true);box('#a98d6a',-W*.34,3.8,-D*.2,W*.17,7.6,D*.24,g);}
  else if(['research','enterprise','youth'].includes(k)){hall(g,-W*.18,-D*.12,W*.56,D*.58,5.5,'#a9c1bc');for(let j=0;j<3;j++){const panel=box(mat('#355f72',.3,.4),-W*.35+j*W*.16,5.9,-D*.15,W*.13,.08,1.7,g);panel.rotation.x=-.15;}canopy(g,W*.22,D*.16,W*.33,D*.40,'#78999c');bench(g,W*.23,D*.19);}
  else if(['culture','community'].includes(k)){hall(g,-W*.22,-D*.22,W*.42,D*.4,4.1,'#ba886a','gable');for(let j=0;j<3;j++)box('#d3c5a7',W*.13,.25+j*.25,D*.13+j*.45,W*.46,.25,D*.25,g);canopy(g,W*.13,D*.06,W*.48,D*.35,'#6c9291');shape('sphere','#bca47e',-W*.25,1.7,D*.22,.7,1.1,.7,g);}
  else{hall(g,-W*.2,-D*.16,W*.45,D*.52,5.6,'#c3b99b');hall(g,W*.24,-D*.24,W*.30,D*.3,3.4,'#a4bdb1');canopy(g,W*.16,D*.22,W*.4,D*.3);bench(g,W*.14,D*.25);}
  for(const x of [-W*.32,W*.32])T.planter(x,.3,D*.38,Math.min(3,W*.2),.9,g);
  g.updateMatrixWorld(true);let bounds=new THREE.Box3().setFromObject(g),size=bounds.getSize(new THREE.Vector3()),mid=bounds.getCenter(new THREE.Vector3()),sc=Math.min(1,(p.usableW-1)/size.x,(p.usableD-1)/size.z);g.scale.set(sc,1,sc);g.position.set(p.x-mid.x*sc,0,p.z-mid.z*sc);g.updateMatrixWorld(true);bounds.setFromObject(g);size=bounds.getSize(new THREE.Vector3());art.reserve(p.x,p.z,size.x+.8,size.z+.8);
  const pick=new THREE.Mesh(new THREE.BoxGeometry(size.x,size.y,size.z),new THREE.MeshBasicMaterial({visible:false}));pick.position.copy(bounds.getCenter(new THREE.Vector3()));pick.userData.theme=p.policyId;scene.add(pick);picks.push(pick);
  records.push({id:p.id,kind:'policy-amenity',theme:p.policyId,x:p.x,z:p.z,w:size.x,d:size.z,height:bounds.max.y,bounds:{min:bounds.min.toArray(),max:bounds.max.toArray()},site:{x:p.x,z:p.z,w:p.usableW,d:p.usableD}});
 }
 return {records,picks};
}
export function buildPolicyCampus(art,scene,p,details,kit){const before=new Set(scene.children);if(!details.policy(p))kit.policy(p);const roots=scene.children.filter(o=>!before.has(o)&&o.isGroup);if(!roots.length)throw Error('Missing campus root '+p.id);const root=roots[0];root.updateMatrixWorld(true);let b=new THREE.Box3().setFromObject(root),size=b.getSize(new THREE.Vector3()),mid=b.getCenter(new THREE.Vector3()),scale=Math.min(1,(p.usableW-1)/size.x,(p.usableD-1)/size.z);root.scale.x*=scale;root.scale.z*=scale;root.position.x=p.x-(mid.x-root.position.x)*scale;root.position.z=p.z-(mid.z-root.position.z)*scale;root.updateMatrixWorld(true);b.setFromObject(root);p.height=b.max.y;p.anchor=new THREE.Vector3(p.x,p.height+2,p.z);p.actualBounds={min:b.min.toArray(),max:b.max.toArray()};}
